//! Event webhook endpoints (administrators only). The signing secret is generated by Moss, returned once (on create and
//! on rotate) and never again; responses only say it is set. URLs are never written to logs or the activity log.
use super::*;
use crate::webhooks::{self, EVENT_TYPES, Endpoint, deliver::Opts, queue, secrets};

#[derive(Deserialize, Default)]
pub(super) struct Body { name: Option<String>, url: Option<String>, events: Option<Vec<String>>, server_ids: Option<Vec<String>>, enabled: Option<bool> }

fn v(field: &str, m: &str) -> ApiError { ApiError::bad("validation", m.to_string()).field(field, m) }

fn name(s: &str) -> ApiResult<String> {
    let s = s.trim();
    if s.is_empty() || s.chars().count() > 60 || s.chars().any(char::is_control) { return Err(v("name", "Give the webhook a name of up to 60 characters.")); }
    Ok(s.to_string())
}

fn url(st: &St, s: &str) -> ApiResult<String> {
    let s = s.trim();
    let u = reqwest::Url::parse(s).map_err(|_| v("url", "Enter a full address such as https://example.com/hook."))?;
    if s.len() > 500 { return Err(v("url", "At most 500 characters.")); }
    if u.scheme() != "https" { return Err(v("url", "The address must start with https://.")); }
    let Some(host) = u.host_str().filter(|h| !h.is_empty()) else { return Err(v("url", "The address has no host name.")) };
    if !u.username().is_empty() || u.password().is_some() { return Err(v("url", "Do not put a user name or password in the address.")); }
    if let Ok(ip) = host.trim_matches(['[', ']']).parse::<std::net::IpAddr>() && !st.cfg.allow_private_webhooks && !crate::notify::webhook::is_public_ip(ip) {
        return Err(v("url", "That is a private or local address. Moss only delivers to public addresses unless the administrator allows private webhooks."));
    }
    Ok(s.to_string())
}

fn events(l: &[String]) -> ApiResult<Vec<String>> {
    let mut out: Vec<String> = vec![];
    for e in l {
        if !webhooks::is_event(e) { return Err(v("events", &format!("Unknown event {e}."))); }
        if !out.contains(e) { out.push(e.clone()); }
    }
    if out.is_empty() { return Err(v("events", "Choose at least one event.")); }
    Ok(out)
}

async fn server_ids(st: &St, l: &[String]) -> ApiResult<Vec<String>> {
    let known: Vec<String> = server::list(st).await?.into_iter().map(|s| s.id).collect();
    let mut out: Vec<String> = vec![];
    for i in l {
        if !known.contains(i) { return Err(v("server_ids", "One of the chosen servers no longer exists.")); }
        if !out.contains(i) { out.push(i.clone()); }
    }
    Ok(out)
}

fn render(e: &Endpoint, secret_set: bool, pending: i64, last: Option<Value>) -> Value {
    json!({"id": e.id, "name": e.name, "url": e.url, "events": e.events, "server_ids": e.server_ids, "enabled": e.enabled, "disabled_reason": e.disabled_reason,
        "consecutive_failures": e.failures, "secret": if secret_set { "set" } else { "not set" }, "pending": pending, "last_delivery": last, "created_at": e.created_at})
}

fn delivery_stats(c: &rusqlite::Connection, id: &str) -> rusqlite::Result<(i64, Option<Value>)> {
    let n = c.query_row("SELECT COUNT(*) FROM webhook_deliveries WHERE endpoint_id=? AND state='pending'", [id], |r| r.get(0))?;
    let last = c.query_row("SELECT state,COALESCE(finished_at,created_at),status_code FROM webhook_deliveries WHERE endpoint_id=? AND test=0 AND state!='pending' ORDER BY created_at DESC, id DESC LIMIT 1", [id],
        |r| Ok(json!({"state": r.get::<_, String>(0)?, "at": r.get::<_, String>(1)?, "status_code": r.get::<_, Option<i64>>(2)?}))).map(Some).or_else(|e| if matches!(e, rusqlite::Error::QueryReturnedNoRows) { Ok(None) } else { Err(e) })?;
    Ok((n, last))
}

async fn view(st: &St, e: &Endpoint) -> ApiResult<Value> {
    let id = e.id.clone();
    let (pending, last) = st.db.call(move |c| delivery_stats(c, &id)).await?;
    let dir = st.cfg.data_dir.clone();
    let id = e.id.clone();
    let set = tokio::task::spawn_blocking(move || secrets::get(&dir, &id).is_some()).await.unwrap_or(false);
    Ok(render(e, set, pending, last))
}

async fn find(st: &St, id: &str) -> ApiResult<Endpoint> { webhooks::get(st, id).await?.ok_or_else(|| ApiError::not_found("webhook")) }

pub(super) async fn webhooks_list(State(st): State<St>, user: User) -> ApiResult<Json<Value>> {
    user.require_admin()?;
    let eps = webhooks::list(&st).await?;
    let ids: Vec<String> = eps.iter().map(|e| e.id.clone()).collect();
    let stats = st.db.call(move |c| ids.iter().map(|id| delivery_stats(c, id)).collect::<rusqlite::Result<Vec<_>>>()).await?;
    let dir = st.cfg.data_dir.clone();
    let ids: Vec<String> = eps.iter().map(|e| e.id.clone()).collect();
    let set: Vec<bool> = tokio::task::spawn_blocking(move || ids.iter().map(|id| secrets::get(&dir, id).is_some()).collect()).await.unwrap_or_default();
    let items: Vec<Value> = eps.iter().zip(stats).enumerate().map(|(n, (e, (p, l)))| render(e, set.get(n).copied().unwrap_or(false), p, l)).collect();
    Ok(Json(json!({"items": items, "event_types": EVENT_TYPES.iter().map(|(t, d)| json!({"type": t, "description": d})).collect::<Vec<_>>()})))
}

pub(super) async fn webhooks_create(State(st): State<St>, user: User, Json(b): Json<Body>) -> ApiResult<(StatusCode, Json<Value>)> {
    user.require_admin()?;
    let e = Endpoint {
        id: uuid::Uuid::now_v7().to_string(), name: name(b.name.as_deref().unwrap_or(""))?, url: url(&st, b.url.as_deref().unwrap_or(""))?,
        events: events(&b.events.unwrap_or_default())?, server_ids: server_ids(&st, &b.server_ids.unwrap_or_default()).await?,
        enabled: b.enabled.unwrap_or(true), failures: 0, disabled_reason: None, created_at: crate::db::now(),
    };
    let secret = secrets::generate();
    secrets::set(&st.cfg.data_dir, &e.id, &secret)?;
    let e2 = e.clone();
    if let Err(err) = st.db.call(move |c| c.execute("INSERT INTO webhook_endpoints(id,name,url,events,server_ids,enabled,created_at) VALUES (?,?,?,?,?,?,?)",
        rusqlite::params![e2.id, e2.name, e2.url, json!(e2.events).to_string(), json!(e2.server_ids).to_string(), e2.enabled, e2.created_at])).await { let _ = secrets::remove(&st.cfg.data_dir, &e.id); return Err(err.into()); }
    st.audit(&user.actor(), "webhook.add", &e.name, "", None).await;
    let mut out = view(&st, &e).await?;
    out["secret"] = json!(secret);
    Ok((StatusCode::CREATED, Json(out)))
}

pub(super) async fn webhooks_patch(State(st): State<St>, user: User, Path(id): Path<String>, Json(b): Json<Body>) -> ApiResult<Json<Value>> {
    user.require_admin()?;
    let mut e = find(&st, &id).await?;
    if let Some(n) = &b.name { e.name = name(n)?; }
    if let Some(u) = &b.url { e.url = url(&st, u)?; }
    if let Some(l) = &b.events { e.events = events(l)?; }
    if let Some(l) = &b.server_ids { e.server_ids = server_ids(&st, l).await?; }
    if let Some(on) = b.enabled {
        if on && !e.enabled { e.failures = 0; e.disabled_reason = None; }
        if !on && e.enabled { e.disabled_reason = None; }
        e.enabled = on;
    }
    let e2 = e.clone();
    st.db.call(move |c| c.execute("UPDATE webhook_endpoints SET name=?,url=?,events=?,server_ids=?,enabled=?,failures=?,disabled_reason=? WHERE id=?",
        rusqlite::params![e2.name, e2.url, json!(e2.events).to_string(), json!(e2.server_ids).to_string(), e2.enabled, e2.failures, e2.disabled_reason, e2.id])).await?;
    if e.enabled { queue::wake(); }
    st.audit(&user.actor(), "webhook.update", &e.name, if e.enabled { "enabled" } else { "disabled" }, None).await;
    Ok(Json(view(&st, &e).await?))
}

pub(super) async fn webhooks_delete(State(st): State<St>, user: User, Path(id): Path<String>) -> ApiResult<StatusCode> {
    user.require_admin()?;
    let e = find(&st, &id).await?;
    let i = id.clone();
    st.db.call(move |c| c.execute("DELETE FROM webhook_endpoints WHERE id=?", [i])).await?;
    let _ = secrets::remove(&st.cfg.data_dir, &id);
    st.audit(&user.actor(), "webhook.remove", &e.name, "", None).await;
    Ok(StatusCode::NO_CONTENT)
}

pub(super) async fn webhooks_rotate(State(st): State<St>, user: User, Path(id): Path<String>) -> ApiResult<Json<Value>> {
    user.require_admin()?;
    let e = find(&st, &id).await?;
    let secret = secrets::generate();
    secrets::set(&st.cfg.data_dir, &id, &secret)?;
    st.audit(&user.actor(), "webhook.rotate_secret", &e.name, "", None).await;
    Ok(Json(json!({"secret": secret})))
}

pub(super) async fn webhooks_test(State(st): State<St>, user: User, Path(id): Path<String>) -> ApiResult<Json<Value>> {
    user.require_admin()?;
    let e = find(&st, &id).await?;
    let d = queue::send_test(&st, &e, Opts { allow_private: st.cfg.allow_private_webhooks, allow_http: false }, &user.email).await?;
    st.audit(&user.actor(), "webhook.test", &e.name, if d["state"] == "delivered" { "delivered" } else { "failed" }, None).await;
    Ok(Json(json!({"delivery": d})))
}

pub(super) async fn webhooks_deliveries(State(st): State<St>, user: User, Path(id): Path<String>) -> ApiResult<Json<Value>> {
    user.require_admin()?;
    find(&st, &id).await?;
    Ok(Json(json!({"items": queue::deliveries(&st, &id).await?})))
}

pub(super) async fn webhooks_retry(State(st): State<St>, user: User, Path((id, did)): Path<(String, String)>) -> ApiResult<Json<Value>> {
    user.require_admin()?;
    find(&st, &id).await?;
    if !queue::retry(&st, &id, &did).await? { return Err(ApiError::conflict("webhook.not_retryable", "Only deliveries that gave up can be sent again.")); }
    Ok(Json(queue::delivery_json(&st, &did).await?.map_or(json!({}), |d| json!({"delivery": d}))))
}
